/// Comment kinds across Rerail's grammars.
fn is_comment<D: Doc>(node: &Node<'_, D>) -> bool {
    matches!(
        node.kind().as_ref(),
        "comment" | "html_comment" | "blade_comment" | "line_comment" | "block_comment"
    )
}

fn first_code<D: Doc>(root: &Node<'_, D>, source: &str) -> usize {
    let mut first = source.len();
    for node in root.dfs() {
        let text = &source[node.range()];
        if !text.trim().is_empty() && !matches!(node.kind().as_ref(), "hash_bang_line" | "php_tag") {
            first = first.min(node.range().start);
        }
    }
    first
}

fn leading<D: Doc>(node: &Node<'_, D>, source: &str) -> Option<Node<'_, D>> {
    (node.kind() == "block")
        .then(|| node.children().find(|child| is_code(child, source)))
        .flatten()
}

/// Whether a node kind is a comment's, in any grammar.
pub(super) fn is_comment_kind(kind: &str) -> bool {
    matches!(kind, "comment" | "html_comment" | "line_comment" | "block_comment")
}

fn named_children<'r, D: Doc>(node: &Node<'r, D>) -> Vec<Node<'r, D>> {
    node.children()
        .filter(|child| child.is_named() && !child.kind().ends_with("comment"))
        .collect()
}

impl Arguments {
    fn match_node<'tree, D: Doc>(&self, node: Node<'tree, D>) -> Option<Node<'tree, D>> {
        if node.field("arguments").is_some_and(|arguments| arguments.kind() != "arguments") {
            return None;
        }
        Some(node)
    }
}

fn unparenthesized<'r, D: Doc>(mut node: Node<'r, D>) -> Node<'r, D> {
    while node.kind() == "parenthesized_expression" {
        node = node.child(1).expect("inner");
    }
    node
}

impl Resolves {
    fn holds_in<D: Doc>(&self, node: &Node<'_, D>) -> bool {
        match node.kind().as_ref() {
            "identifier" | "variable_name" => true,
            _ => false,
        }
    }
}

