fn is_attribute<D: Doc>(node: &Node<'_, D>) -> bool {
    node.kind() == "attribute_item"
}

fn is_variable<D: Doc>(node: &Node<'_, D>) -> bool {
    node.kind() == "variable_name"
}

fn is_string<D: Doc>(node: &Node<'_, D>) -> bool {
    matches!(node.kind().as_ref(), "string" | "concatenated_string")
}

fn is_name<D: Doc>(node: &Node<'_, D>) -> bool {
    match node.kind().as_ref() {
        "name" | "qualified_name" => true,
        _ => false,
    }
}

fn is_tag<D: Doc>(node: &Node<'_, D>) -> bool {
    node.kind() == "tag_name"
}

fn comments<'r, D: Doc>(root: &Node<'r, D>) -> impl Iterator<Item = Node<'r, D>> {
    root.dfs().filter(|node| node.kind() == "comment")
}

fn is_call<D: Doc>(node: &Node<'_, D>) -> bool {
    node.kind() == "call"
}

#[derive(Clone, Copy)]
struct Kinds {
    comments: &'static [&'static str],
}

impl Kinds {
    fn of(dialect: GrammarDialect) -> Self {
        with_adapter!(Family::of(dialect), A => Self { comments: A::COMMENT_KINDS })
    }

    fn comment<D: Doc>(self, node: &Node<'_, D>) -> bool {
        self.comments.contains(&node.kind().as_ref())
    }
}

fn separator<D: Doc>(node: &Node<'_, D>) -> bool {
    matches!(node.kind().as_ref(), "," | ";")
}

fn errors<'r, D: Doc>(root: &Node<'r, D>) -> impl Iterator<Item = Node<'r, D>> {
    root.children().filter(|child| child.kind() == "ERROR" || child.kind() == "(")
}

