fn host_kinds(host: LiteralHost, language: GrammarDialect) -> BTreeSet<u16> {
    match host {
        LiteralHost::PythonString => kind_ids(language, &["string", "concatenated_string"]),
        LiteralHost::RustString => kind_ids(language, &["string_literal", "raw_string_literal"]),
    }
}

fn this_boundary(kind: &str) -> Option<ThisBoundary> {
    match kind {
        "method_definition" => Some(ThisBoundary::OwnExcept("name")),
        _ => None,
    }
}

impl Arguments {
    fn match_node<'tree, D: Doc>(&self, node: Node<'tree, D>) -> Option<Node<'tree, D>> {
        // ESTree's TaggedTemplateExpression has no `arguments`.
        if self.estree
            && node.field("arguments").is_some_and(|arguments| arguments.kind() != "arguments")
        {
            return None;
        }
        Some(node)
    }
}

fn trans(entry: &Map<String, Value>, path: &str) -> Result<Trans, String> {
    let [(kind, body)] = entry.iter().collect::<Vec<_>>()[..] else {
        return Err(format!("{path} must hold exactly one transformation"));
    };
    Ok(match kind.as_str() {
        "replace" => Trans::replace(body)?,
        _ => return Err(format!("{path}/{kind} is unknown")),
    })
}

fn reference_kinds<S: ScopeRules>(language: GrammarDialect) -> BTreeSet<u16> {
    kind_ids(language, S::REFERENCE_KINDS)
}
